use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    let mtx_a = Arc::new(Mutex::new(()));
    let mtx_b = Arc::new(Mutex::new(()));
    let mtx_c = Arc::new(Mutex::new(()));

    // Global lock order: A < B < C.
    // Every worker acquires its two mutexes in this order, which makes a
    // circular wait impossible, so every interleaving terminates.

    let (a1, b1) = (Arc::clone(&mtx_a), Arc::clone(&mtx_b));
    let w1 = thread::spawn(move || {
        let ga = a1.lock().unwrap(); // A then B: correct order
        let gb = b1.lock().unwrap();
        drop(gb);
        drop(ga);
    });

    let (b2, c2) = (Arc::clone(&mtx_b), Arc::clone(&mtx_c));
    let w2 = thread::spawn(move || {
        let gb = b2.lock().unwrap(); // B then C: correct order
        let gc = c2.lock().unwrap();
        drop(gc);
        drop(gb);
    });

    let (a3, c3) = (Arc::clone(&mtx_a), Arc::clone(&mtx_c));
    let w3 = thread::spawn(move || {
        // Was C then A, which created a cycle (A->B, B->C, C->A).
        // Now acquire in global order: A first, then C.
        let ga = a3.lock().unwrap();
        let gc = c3.lock().unwrap();
        drop(gc);
        drop(ga);
    });

    w1.join().unwrap();
    w2.join().unwrap();
    w3.join().unwrap();

    println!("DONE done=1");
}
